import { memo, useEffect } from "react";
import { useGLTF } from "@react-three/drei";
// #if DEBUG
import { useControls } from "leva";
// #endif
import { useScene } from "@/lib/contexts/SceneContext";
import InteractionZone from "@/components/three/InteractionZone";
import { enableShadows } from "@/utils/three";

type DoorControls = {
    doorX: number;
    doorScale: number;
    doorBoxSizeX: number;
    doorBoxSizeY: number;
    doorBoxSizeZ: number;
    doorBoxAnchorX: number;
    doorBoxAnchorY: number;
    doorBoxAnchorZ: number;
};

// Generated by .bin/generate-scene-models.mts 1 unit tall, with its bottom
// center at the origin and its back on the wall, so `door.scale` is its height
const DOOR_MODEL_PATH = "/models/cartoon_door.glb";
const DOOR_MESSAGE = "Leaving already?";

const Door = memo(() => {
    const { door } = useScene();
    const doorModel = useGLTF(DOOR_MODEL_PATH);

    useEffect(() => {
        enableShadows(doorModel.scene);
    }, [doorModel.scene]);

    let doorX: number, doorScale: number;
    let doorBoxSizeX: number,
        doorBoxSizeY: number,
        doorBoxSizeZ: number,
        doorBoxAnchorX: number,
        doorBoxAnchorY: number,
        doorBoxAnchorZ: number;

    // #if DEBUG
    ({
        doorX,
        doorScale,
        doorBoxSizeX,
        doorBoxSizeY,
        doorBoxSizeZ,
        doorBoxAnchorX,
        doorBoxAnchorY,
        doorBoxAnchorZ,
    } = useControls(
        "Door",
        {
            doorX: {
                value: door?.position?.x ?? 0,
                min: -12,
                max: 12,
                step: 0.01,
            },
            doorScale: {
                value: door?.scale ?? 1,
                min: 4,
                max: 11,
                step: 0.01,
            },
            doorBoxSizeX: {
                value: door?.boxSize?.x ?? 6,
                min: 0.1,
                max: 20,
                step: 0.01,
            },
            doorBoxSizeY: {
                value: door?.boxSize?.y ?? 8,
                min: 0.1,
                max: 20,
                step: 0.01,
            },
            doorBoxSizeZ: {
                value: door?.boxSize?.z ?? 4,
                min: 0.1,
                max: 20,
                step: 0.01,
            },
            doorBoxAnchorX: {
                value: door?.boxAnchor?.x ?? 0,
                min: -10,
                max: 10,
                step: 0.01,
            },
            doorBoxAnchorY: {
                value: door?.boxAnchor?.y ?? 4,
                min: -10,
                max: 10,
                step: 0.01,
            },
            doorBoxAnchorZ: {
                value: door?.boxAnchor?.z ?? 2,
                min: -10,
                max: 10,
                step: 0.01,
            },
        },
        { collapsed: true }
    ) as DoorControls);
    // #endif

    // #if !DEBUG
    doorX = door?.position?.x ?? 0;
    doorScale = door?.scale ?? 1;
    doorBoxSizeX = door?.boxSize?.x ?? 6;
    doorBoxSizeY = door?.boxSize?.y ?? 8;
    doorBoxSizeZ = door?.boxSize?.z ?? 4;
    doorBoxAnchorX = door?.boxAnchor?.x ?? 0;
    doorBoxAnchorY = door?.boxAnchor?.y ?? 4;
    doorBoxAnchorZ = door?.boxAnchor?.z ?? 2;
    // #endif

    return (
        <group
            position={[doorX, door?.position?.y ?? 0, door?.position?.z ?? 0]}
            rotation={[0, door?.rotation?.y ?? 0, 0]}
        >
            <primitive
                object={doorModel.scene}
                scale={[doorScale, doorScale, doorScale]}
            />
            <InteractionZone
                message={DOOR_MESSAGE}
                size={[doorBoxSizeX, doorBoxSizeY, doorBoxSizeZ]}
                center={[doorBoxAnchorX, doorBoxAnchorY, doorBoxAnchorZ]}
            />
        </group>
    );
});
Door.displayName = "Door";

useGLTF.preload(DOOR_MODEL_PATH);

export default Door;
